def handle_login(request):
    """POST /login handler."""
    body = request.get("body", {})
    token = login(body.get("username"), body.get("password"))
    if token is None:
        return {"status": 401, "error": "invalid credentials or locked out"}
    return {"status": 200, "token": token}

